insert into branches(id,code,name) values('10000000-0000-0000-0000-000000000001','A','Ficticia A'),('10000000-0000-0000-0000-000000000002','B','Ficticia B'),('10000000-0000-0000-0000-000000000003','C','Ficticia C');
insert into profiles(id,full_name) select ('20000000-0000-0000-0000-00000000000'||x)::uuid,'Persona ficticia '||x from generate_series(1,6)x;
insert into user_roles select p.id,r.id,b.id from profiles p cross join branches b join roles r on r.code=case right(p.id::text,1) when '1' then 'LOGISTICA_SUPERVISOR' when '2' then 'LOGISTICA_CONDUCTOR' when '3' then 'LOGISTICA_CONDUCTOR' when '4' then 'LABORATORIO' when '5' then 'LOGISTICA_CONDUCTOR' else 'LOGISTICA_CONSULTA' end where right(p.id::text,1) in ('1','2','3','6') and b.code in ('A','B') or right(p.id::text,1)='4' and b.code='B' or right(p.id::text,1)='5' and b.code='C';
insert into transport_events(id,branch_id,transport_code,min_temp,max_temp) values('30000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','DEMO-001',2,6),('30000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000001','DEMO-002',2,6);
create function public.test_ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function public.test_denied(stmt text,label text) returns void language plpgsql as $$begin begin execute stmt;exception when others then raise notice 'PASS %',label;return;end;raise exception 'FAIL unexpected authorization %',label;end$$;
create function public.test_payload(n integer,a jsonb default '{}'::jsonb) returns jsonb language sql as $$select a||jsonb_build_object('request_id',('40000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid)$$;
create function public.test_current(n integer) returns jsonb language sql as $$select test_payload(n,jsonb_build_object('id',id,'revision',revision)) from team_deliveries where transport_id='30000000-0000-0000-0000-000000000001'$$;
select test_ok((select not enabled from app_feature_flags where key='team_delivery_coordination'),'flag defaults off');
set role authenticated;select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',false);
select test_denied($q$select team_delivery_action('CREATE',test_payload(1,'{"transport_id":"30000000-0000-0000-0000-000000000001","destination_branch_id":"10000000-0000-0000-0000-000000000002","driver_id":"20000000-0000-0000-0000-000000000002"}'))$q$,'disabled flag blocks writes');
reset role;update app_feature_flags set enabled=true where key='team_delivery_coordination';insert into team_delivery_pilot values('10000000-0000-0000-0000-000000000001',true);
set role authenticated;select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',false);
select test_denied($q$select team_delivery_action('CREATE',test_payload(1,'{"transport_id":"30000000-0000-0000-0000-000000000001","destination_branch_id":"10000000-0000-0000-0000-000000000002","driver_id":"20000000-0000-0000-0000-000000000002"}'))$q$,'driver cannot self-assign');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',false);
select test_denied($q$select team_delivery_action('CREATE',test_payload(1,'{"transport_id":"30000000-0000-0000-0000-000000000001","destination_branch_id":"10000000-0000-0000-0000-000000000002","driver_id":"20000000-0000-0000-0000-000000000005"}'))$q$,'driver needs both branch assignments');
select team_delivery_action('CREATE',test_payload(1,'{"transport_id":"30000000-0000-0000-0000-000000000001","destination_branch_id":"10000000-0000-0000-0000-000000000002","driver_id":"20000000-0000-0000-0000-000000000002"}'));
select team_delivery_action('CREATE',test_payload(1,'{"transport_id":"30000000-0000-0000-0000-000000000001","destination_branch_id":"10000000-0000-0000-0000-000000000002","driver_id":"20000000-0000-0000-0000-000000000002"}'));
select test_ok((select count(*)=1 from team_delivery_history),'idempotent retry creates one event');
select test_denied($q$select team_delivery_action('CREATE',test_payload(1,'{"transport_id":"30000000-0000-0000-0000-000000000002"}'))$q$,'same key different body rejected');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000003',false);
select test_ok((select count(*)=1 from team_deliveries),'second driver sees team delivery');
select test_denied($q$select team_delivery_action('DEPART',test_current(2))$q$,'unassigned driver cannot depart');
select test_denied($q$update team_deliveries set driver_id=auth.uid()$q$,'direct assignment updates denied');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',false);
select team_delivery_action('DEPART',test_current(2));
select test_denied($q$select team_delivery_action('DELIVER',test_current(3)||'{"revision":1,"reference":"Demo"}')$q$,'stale revision rejected');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',false);
select team_delivery_action('REASSIGN',test_current(4)||'{"driver_id":"20000000-0000-0000-0000-000000000003","reason":"Relevo ficticio"}');
select test_ok((select driver_id='20000000-0000-0000-0000-000000000002' from team_deliveries),'reassignment retains current responsibility until accepted');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',false);
select test_denied($q$select team_delivery_action('DELIVER',test_current(5)||'{"reference":"Demo"}')$q$,'pending handover blocks old driver execution');
select test_denied($q$select team_delivery_action('ACCEPT',test_current(6))$q$,'old driver cannot accept new responsibility');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000003',false);
select team_delivery_action('ACCEPT',test_current(7));
select team_delivery_action('DELIVER',test_current(8)||'{"reference":"ENTREGA-DEMO"}');
select test_denied($q$select team_delivery_action('RECEIVE',test_current(9)||'{"temperature":"4","condition":"CONFORME","evidence":"Demo"}')$q$,'driver cannot receive for laboratory');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000004',false);
select test_ok((select count(*)=1 from team_deliveries),'destination laboratory sees source delivery');
select test_denied($q$select team_delivery_action('RECEIVE',test_current(9)||'{"temperature":"NaN","condition":"CONFORME","evidence":"Demo"}')$q$,'nonfinite temperature denied');
select team_delivery_action('RECEIVE',test_current(10)||'{"temperature":"9","condition":"CONFORME","evidence":"EVIDENCIA-DEMO"}');
select test_ok((select status='INCIDENCIA_RECEPCION' and received_by=auth.uid() from team_deliveries),'out of range registers incident and actual receiver');
select test_denied($q$select team_delivery_action('RECEIVE',test_current(11)||'{"temperature":"4","condition":"CONFORME","evidence":"Demo"}')$q$,'second reception rejected');
select test_ok((select count(*)=6 from team_delivery_history),'all definitive actions have atomic history');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000005',false);
select test_ok((select count(*)=0 from team_deliveries),'unassigned branch cannot read team');
select test_ok((select count(*)=0 from team_delivery_history),'unassigned branch cannot read history');
select test_ok((team_delivery_catalog()->'transports')='[]'::jsonb,'driver cannot list clinical transport catalog');
reset role;update profiles set active=false where id='20000000-0000-0000-0000-000000000003';set role authenticated;select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000003',false);
select test_ok((select count(*)=0 from team_deliveries),'inactive account loses read access');
reset role;set role anon;select test_denied($q$select team_delivery_catalog()$q$,'anonymous catalog denied');select test_denied($q$select * from team_deliveries$q$,'anonymous records denied');
reset role;
select test_ok((select bool_and(status='EN_TRANSITO') from transport_events),'clinical transport state unchanged');
select test_ok(not has_table_privilege('authenticated','team_delivery_history','UPDATE') and not has_table_privilege('authenticated','team_delivery_history','DELETE'),'history append only through guarded RPC');
